package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsAny(CharSequence, char[])
 */
public class StringUtils_containsAny_TriageGen2Test {

    @Test
    public void testContainsAny_NullCharSequence() {
        assertFalse("Should return false when CharSequence is null", 
            StringUtils.containsAny(null, new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_EmptyCharSequence() {
        assertFalse("Should return false when CharSequence is empty", 
            StringUtils.containsAny("", new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        assertFalse("Should return false when searchChars array is null", 
            StringUtils.containsAny("abc", null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        assertFalse("Should return false when searchChars array is empty", 
            StringUtils.containsAny("abc", new char[]{}));
    }

    @Test
    public void testContainsAny_NoMatch() {
        assertFalse("Should return false when no characters match", 
            StringUtils.containsAny("abcdef", new char[]{'x', 'y', 'z'}));
    }

    @Test
    public void testContainsAny_SingleMatchAtStart() {
        assertTrue("Should return true when first character matches", 
            StringUtils.containsAny("abc", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_SingleMatchAtEnd() {
        assertTrue("Should return true when last character matches", 
            StringUtils.containsAny("abc", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_MultipleMatches() {
        assertTrue("Should return true when multiple characters match", 
            StringUtils.containsAny("abcde", new char[]{'b', 'd'}));
    }

    @Test
    public void testContainsAny_SearchCharsLongerThanCs() {
        assertTrue("Should return true when search array is larger than input", 
            StringUtils.containsAny("a", new char[]{'z', 'y', 'a', 'x'}));
    }

    @Test
    public void testContainsAny_UnicodeBMP() {
        // Testing Basic Multilingual Plane characters
        assertTrue("Should handle BMP characters correctly", 
            StringUtils.containsAny("Hello ©", new char[]{'©'}));
    }

    @Test
    public void testContainsAny_CaseSensitivity() {
        // The implementation uses == on char, so it is case sensitive
        assertFalse("Should be case sensitive", 
            StringUtils.containsAny("abc", new char[]{'A'}));
    }
}
